
DROP TABLE IF EXISTS #tempLeagueSettings;
CREATE TABLE #tempLeagueSettings (
    num INT,
    LeagueGroup NVARCHAR(255),
    LeagueName NVARCHAR(255),
    TV NVARCHAR(255),
    Round NVARCHAR(255),
    Division NVARCHAR(255),
    Remark NVARCHAR(255),
    Spread NVARCHAR(255),
    MaxbetWD_HDP NVARCHAR(255),
    WD_NoOfHDP NVARCHAR(255),
    MaxbetWK_HDP NVARCHAR(255),
    WK_NoOfHDP NVARCHAR(255)
);






